// 模拟 Reno 拥塞窗口随 ACK / 丢包事件的状态变化
// 关键变量：
//   cwnd       当前拥塞窗口（单位 MSS）
//   ssthresh   慢启动阈值，触发 SS -> CA 切换
//   state      当前阶段：slow_start / congestion_avoidance / fast_recovery
class RenoSimulator {
    double cwnd = 10.0;        // Linux 默认 IW = 10 MSS（RFC 6928）
    double ssthresh = 64.0;    // 初始阈值，单位 MSS
    String state = "slow_start";
    int dupAckCount = 0;

    // 收到一个新 ACK
    void onNewAck() {
        switch (state) {
            case "slow_start":
                cwnd += 1.0;                // 每 ACK +1 MSS，一个 RTT 内翻倍
                if (cwnd >= ssthresh) state = "congestion_avoidance";
                break;
            case "congestion_avoidance":
                cwnd += 1.0 / cwnd;         // 累计 MSS^2/cwnd，一个 RTT +1 MSS
                break;
            case "fast_recovery":
                cwnd = ssthresh;            // 退出快恢复，回到 CA
                state = "congestion_avoidance";
                break;
        }
        dupAckCount = 0;
    }

    // 收到一个重复 ACK（按序号没前进）
    void onDupAck() {
        dupAckCount++;
        if (state.equals("fast_recovery")) {
            cwnd += 1.0;                    // 维持管道：每多一个 dupACK 拉一格
            return;
        }
        if (dupAckCount == 3) {             // 触发快重传 + 快恢复
            ssthresh = Math.max(cwnd / 2, 2);
            cwnd = ssthresh + 3;            // +3 是已离开网络的 3 个报文
            state = "fast_recovery";
            // 这里调用底层立即重传 SND.UNA 对应的报文
        }
    }

    // RTO 超时：视为严重拥塞，退回慢启动
    void onRto() {
        ssthresh = Math.max(cwnd / 2, 2);
        cwnd = 1.0;                         // 也可改成 IW=10 模拟较新内核
        state = "slow_start";
        dupAckCount = 0;
    }
}
